import fs from "node:fs";
import { setMaxListeners } from "node:events";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { AgentRuntime } from "arcbench-agent-runtime-js";
import {
  AuthStorage,
  ModelRegistry,
  createAgentSession,
  DefaultResourceLoader,
  SessionManager,
} from "@earendil-works/pi-coding-agent";
import type { ThinkingLevel } from "@earendil-works/pi-agent-core";
import { buildEmbeddedContext, buildImplementationBrief, listRelativeFiles } from "./src/context/contextBuilder.js";
import { analyzeStarterProject, buildStarterSnapshot } from "./src/context/starterSnapshot.js";
import { seedBundledTemplateIfEmpty } from "./src/context/starterProject.js";
import { ModelCallMetricsRecorder } from "./src/telemetry/tokenMetrics.js";
import { DiagnosticReporter } from "./src/telemetry/diagnosticReport.js";
import { ValidationLogCollector } from "./src/validation/failureDigest.js";
import { HandoffStore } from "./src/context/handoffStore.js";
import { classifyTask } from "./src/requirements/classifier.js";
import { formatNodeDirectory, parseRequirements } from "./src/requirements/parser.js";
import { buildWorkGraph } from "./src/requirements/workGraph.js";
import { splitLargeRequirementSet } from "./src/requirements/largeTaskSplitter.js";
import { runNodeSchedule } from "./src/orchestration/nodeScheduler.js";
import { applyHiddenTaskModelPolicy } from "./src/orchestration/modelPolicy.js";
import { runRepairSession } from "./src/orchestration/repairRunner.js";
import { ensureProjectDependencies, prepareEvaluationState, validateProject } from "./src/validation/validator.js";
import {
  buildContractTestPrompt,
  cleanupGeneratedContracts,
  restoreGeneratedContracts,
  restoreProductSources,
  shouldGenerateRequirementContracts,
  snapshotGeneratedContracts,
  snapshotProductSources,
  writeContractPackets,
} from "./src/validation/contractVerification.js";
import { stagePublicTests } from "./src/validation/publicTestStaging.js";
import { batchWorkNodes, recommendedWorkSessions } from "./src/requirements/workBatcher.js";
import { detectCapabilities } from "./src/blueprints/catalog.js";
import { formatPreparedCapabilities, prepareCapabilities } from "./src/blueprints/installer.js";
import { RuntimeReporter } from "./src/runtime/runtimeReporter.js";

// Pi reuses an AbortSignal across many tool calls; raise the diagnostic threshold for long ARC tasks.
setMaxListeners(100);

type AgentArgs = {
  requirementPath: string;
  outputDir: string;
  taskType: string;
};

type ModelConfigEnv = {
  apiKey: string;
  baseUrl: string;
  model: string;
  thinkingLevel: ThinkingLevel;
  tools: string[];
};

function parseArgs(argv: string[]): AgentArgs {
  const args: AgentArgs = {
    requirementPath: process.env.ARCBENCH_TASK_DIR || "requirements",
    outputDir: process.env.ARCBENCH_OUTPUT_DIR || ".",
    taskType: process.env.ARCBENCH_TASK_TYPE || "web",
  };
  const positional: string[] = [];
  for (let index = 0; index < argv.length; index += 1) {
    const value = argv[index];
    if (value === "--output-dir") {
      args.outputDir = argv[++index] || args.outputDir;
    } else if (value === "--type") {
      args.taskType = argv[++index] || args.taskType;
    } else {
      positional.push(value);
    }
  }
  if (positional[0]) {
    args.requirementPath = positional[0];
  }
  return args;
}

function getModelConfigFromEnv(): ModelConfigEnv {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY is required.");
  }
  return {
    apiKey,
    baseUrl: process.env.OPENAI_BASE_URL || "https://api.openai.com/v1",
    model: process.env.MODEL || "deepseek-v4-flash",
    thinkingLevel: getThinkingLevelFromEnv(),
    tools: getToolsFromEnv(),
  };
}

function ensureDir(dirPath: string): void {
  fs.mkdirSync(dirPath, { recursive: true });
}

function optionalPositiveEnv(name: string): number | undefined {
  const raw = process.env[name];
  if (raw === undefined || raw.trim() === "") return undefined;
  const value = Number(raw);
  if (!Number.isFinite(value) || value <= 0) throw new Error(`${name} must be a positive number when set.`);
  return value;
}

function getThinkingLevelFromEnv(): ThinkingLevel {
  const rawLevel = (process.env.PI_THINKING_LEVEL || "low").trim().toLowerCase();
  if (rawLevel === "off" || rawLevel === "low" || rawLevel === "medium" || rawLevel === "high") {
    return rawLevel;
  }
  throw new Error(`Unsupported PI_THINKING_LEVEL: ${rawLevel}`);
}

function getToolsFromEnv(): string[] {
  const rawTools = process.env.PI_TOOLS || "read,edit,write,bash,grep,find,ls";
  return rawTools
    .split(",")
    .map((tool) => tool.trim())
    .filter(Boolean);
}

function writePiModelsConfig(runtimeDir: string, modelConfig: ModelConfigEnv): string {
  ensureDir(runtimeDir);
  const modelsPath = path.join(runtimeDir, "models.json");
  const config = {
    providers: {
      openai: {
        baseUrl: modelConfig.baseUrl,
      },
      deepseek: {
        baseUrl: modelConfig.baseUrl,
      },
      arcbench: {
        name: "ARC-Bench OpenAI-Compatible",
        baseUrl: modelConfig.baseUrl,
        apiKey: "$OPENAI_API_KEY",
        api: "openai-completions",
        compat: {
          supportsDeveloperRole: false,
          supportsReasoningEffort: false,
          supportsUsageInStreaming: false,
          maxTokensField: "max_tokens",
        },
        models: [
          {
            id: modelConfig.model,
            name: modelConfig.model,
            reasoning: false,
            input: ["text"],
            cost: {
              input: 0,
              output: 0,
              cacheRead: 0,
              cacheWrite: 0,
            },
            contextWindow: 128000,
            maxTokens: 8192,
          },
        ],
      },
    },
  };
  fs.writeFileSync(modelsPath, JSON.stringify(config, null, 2));
  return modelsPath;
}

function resolvePiModel(
  authStorage: AuthStorage,
  modelRegistry: ModelRegistry,
  modelConfig: ModelConfigEnv,
): { providerId: string; model: NonNullable<ReturnType<ModelRegistry["find"]>> } {
  const candidates = [
    { providerId: "deepseek", model: modelRegistry.find("deepseek", modelConfig.model) },
    { providerId: "openai", model: modelRegistry.find("openai", modelConfig.model) },
    { providerId: "arcbench", model: modelRegistry.find("arcbench", modelConfig.model) },
  ];
  const match = candidates.find((candidate) => candidate.model);
  const model = match?.model;
  if (!model) {
    throw new Error(`Unable to load Pi model configuration for ${modelConfig.model}.`);
  }
  authStorage.setRuntimeApiKey(match.providerId, modelConfig.apiKey);
  return { providerId: match.providerId, model };
}

function discoverPublicTestSources(requirementsDir: string, currentDir: string): string[] {
  const candidates = [
    process.env.ARCBENCH_TESTS_DIR,
    process.env.PUBLIC_TESTS_DIR,
    process.env.TESTS_DIR,
    "/workspace/tests",
    path.join(requirementsDir, "tests"),
    path.join(path.dirname(requirementsDir), "tests"),
    path.join(currentDir, "public-tests", process.env.ARCBENCH_REQUIREMENT_ID || path.basename(requirementsDir)),
  ].filter((value): value is string => Boolean(value));
  const seen = new Set<string>();
  const files: string[] = [];
  for (const candidate of candidates) {
    const absolute = path.resolve(candidate);
    if (seen.has(absolute) || !fs.existsSync(absolute) || !fs.statSync(absolute).isDirectory()) continue;
    seen.add(absolute);
    for (const relative of listRelativeFiles(absolute, 4)) {
      if (/\.(?:ts|tsx|js|jsx|json)$/.test(relative)) files.push(path.join(absolute, relative));
    }
  }
  const unique = [...new Set(files)].slice(0, 100);
  return unique;
}

async function runAgent(
  runtime: AgentRuntime,
  requirementsDir: string,
  outputDir: string,
  taskType: string,
): Promise<void> {
  const currentDir = path.dirname(fileURLToPath(import.meta.url));
  const pipelineStartedAt = Date.now();
  const totalBudgetMs = optionalPositiveEnv("PI_TOTAL_BUDGET_MS") ?? 90 * 60 * 1_000;
  const pipelineDeadline = pipelineStartedAt + totalBudgetMs;
  console.log("[orchestrator] total pipeline budget=" + Math.round(totalBudgetMs / 60_000) + " minutes");
  const resumingNodeRun = fs.existsSync(path.join(outputDir, ".arc", "work-nodes"));
  let installedBundledScaffold = false;
  if (!resumingNodeRun) {
    installedBundledScaffold = seedBundledTemplateIfEmpty(path.join(currentDir, "template"), outputDir);
    const seeded = installedBundledScaffold;
    console.log(seeded
      ? "[orchestrator] empty output detected; installed bundled scaffold"
      : "[orchestrator] task starter detected; preserving all supplied project files");
  }
  else console.log("[orchestrator] resume detected; preserving existing project files");
  const diagnostics = new DiagnosticReporter(outputDir, "5.7.4-contract-gated", pipelineStartedAt, totalBudgetMs);
  const signalHandlers = new Map<NodeJS.Signals, () => void>();
  for (const signal of ["SIGTERM", "SIGINT"] as const) {
    const handler = () => {
      diagnostics.interrupted(signal);
      console.error(`[orchestrator] received ${signal}; diagnostic checkpoint written before exit`);
      process.exit(signal === "SIGTERM" ? 143 : 130);
    };
    signalHandlers.set(signal, handler);
    process.once(signal, handler);
  }
  const publicTestSource = process.env.ARCBENCH_TESTS_DIR || "/workspace/tests";
  const stagedPublicTests = stagePublicTests(publicTestSource, outputDir);
  const publicTestSources = discoverPublicTestSources(requirementsDir, currentDir);
  const publicTests = publicTestSources.filter((file) => /\.(?:spec|test)\.(?:ts|tsx|js|jsx)$/i.test(file));
  const parsedRequirements = splitLargeRequirementSet(requirementsDir, parseRequirements(requirementsDir));
  if (parsedRequirements.diagnostics.length) {
    diagnostics.failure("requirement-parsing", parsedRequirements.diagnostics.join("\n"));
    diagnostics.finalize(false, "Requirement parsing failed before model execution.");
    throw new Error("Requirement parsing failed:\n" + parsedRequirements.diagnostics.join("\n"));
  }

  const capabilityMatches = detectCapabilities(parsedRequirements);
  const blueprintInstallation = prepareCapabilities({
    matches: capabilityMatches,
    blueprintsDir: path.join(currentDir, "blueprints"),
    outputDir,
    installFiles: installedBundledScaffold,
    enabled: process.env.PI_PREPARE_BLUEPRINTS !== "0",
  });
  const preparedCapabilityContext = formatPreparedCapabilities(blueprintInstallation);
  console.log("[orchestrator] prepared capabilities="
    + (blueprintInstallation.capabilities.map((item) => item.id).join(",") || "none")
    + " mode=" + blueprintInstallation.mode
    + " installed_files=" + blueprintInstallation.capabilities.reduce((sum, item) => sum + item.installed_files.length, 0));

  const classification = classifyTask(parsedRequirements, publicTests.length);
  const hiddenTestMode = publicTests.length === 0;
  const adaptiveWorkSessions = recommendedWorkSessions(parsedRequirements, hiddenTestMode);
  const defaultPreparedSessions = blueprintInstallation.capabilities.some((capability) =>
    capability.id === "github-collaboration-starter") ? 2 : 1;
  const preparedSessionSetting = Number(process.env.PI_PREPARED_APP_SESSIONS || String(defaultPreparedSessions));
  const preparedWorkSessions = Number.isFinite(preparedSessionSetting)
    ? Math.max(1, Math.min(4, Math.floor(preparedSessionSetting)))
    : defaultPreparedSessions;
  const workSessions = blueprintInstallation.application_seeded && !process.env.PI_MAX_WORK_SESSIONS
    ? Math.min(adaptiveWorkSessions, preparedWorkSessions)
    : adaptiveWorkSessions;
  const requirements = batchWorkNodes(parsedRequirements, workSessions);
  diagnostics.configureTask({
    taskType,
    sourceNodes: parsedRequirements.nodes.length,
    scenarios: parsedRequirements.nodes.reduce((sum, node) => sum + node.scenarios.length, 0),
    characters: parsedRequirements.totalCharacters,
    prepared: blueprintInstallation.application_seeded,
    capabilities: blueprintInstallation.capabilities.map((item) => item.id),
  });
  const runtimeReporter = new RuntimeReporter(runtime);
  runtimeReporter.initialize(parsedRequirements);
  const embeddedContext = buildEmbeddedContext(requirementsDir, publicTestSources);
  const starterAnalysis = analyzeStarterProject(outputDir);
  const starterIsSubstantial = starterAnalysis.substantial
    && (!installedBundledScaffold || blueprintInstallation.application_seeded);
  const hasStructuredRequirements = !(parsedRequirements.nodes.length === 1 && parsedRequirements.nodes[0].id === "ARC-TASK");
  const requirementContext = hasStructuredRequirements
    ? buildImplementationBrief(parsedRequirements)
    : embeddedContext.requirementSummary;
  console.log("[orchestrator] complexity=" + classification.level
    + " score=" + classification.score
    + " implementation_sessions=" + requirements.nodes.length
    + " source_nodes=" + parsedRequirements.nodes.length
    + " context_chars=" + embeddedContext.embeddedCharacters
    + " reasons=" + classification.reasons.join("; "));

  const stagedRequirementRoot = path.join(outputDir, ".arc", "requirements-source");
  for (const sourceFile of requirements.sourceFiles) {
    const sourcePath = path.join(requirementsDir, sourceFile);
    const destination = path.join(stagedRequirementRoot, sourceFile);
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.copyFileSync(sourcePath, destination);
  }

  // Prepared applications are audits of runnable products, not code-reading
  // exercises. Install once before model work so the auditing sessions can run
  // the seed, build, API, and browser flows they are asked to verify. The final
  // validator reuses these same node_modules directories.
  if (blueprintInstallation.application_seeded && process.env.PI_PREINSTALL_PREPARED_APP !== "0") {
    console.log("[orchestrator] preinstalling prepared application dependencies for executable model audit");
    const preparation = ensureProjectDependencies(outputDir, pipelineDeadline);
    if (preparation.ok) {
      console.log("[orchestrator] prepared application dependencies ready");
      diagnostics.dependencyInstall(true, "Prepared frontend/backend dependencies installed successfully.");
    } else {
      const tail = preparation.outputs.join("\n").slice(-2_000).replace(/\s+/g, " ").trim();
      console.warn("[orchestrator] prepared application dependency install failed; model audit will continue: " + tail);
      diagnostics.dependencyInstall(false, tail);
    }
  } else {
    diagnostics.dependencyInstall(true, "Prepared dependency preinstallation was not required.");
  }

  const modelConfig = getModelConfigFromEnv();
  const modelPolicyMessage = blueprintInstallation.application_seeded
    ? "prepared application baseline detected: keeping low thinking and using audit/repair sessions"
    : applyHiddenTaskModelPolicy(modelConfig, hiddenTestMode, classification.level);
  if (modelPolicyMessage) console.log("[orchestrator] " + modelPolicyMessage);
  console.log("[orchestrator] model=" + modelConfig.model + " thinking=" + modelConfig.thinkingLevel + " tools=" + modelConfig.tools.join(","));
  console.log("[orchestrator] invoking generic Pi pipeline for taskType=" + taskType);
  const piRuntimeDir = path.join(currentDir, ".pi-runtime");
  const piAgentHome = path.join(piRuntimeDir, "agent-home");
  const modelsPath = writePiModelsConfig(piRuntimeDir, modelConfig);
  ensureDir(piAgentHome);

  const loadBundledSkills = process.env.PI_LOAD_BUNDLED_SKILLS === "1";
  const resourceLoader = new DefaultResourceLoader({
    cwd: outputDir,
    agentDir: piAgentHome,
    ...(loadBundledSkills ? { additionalSkillPaths: [path.join(currentDir, "skills")] } : {}),
  });
  await resourceLoader.reload();
  const loadedSkillResources = resourceLoader.getSkills();
  console.log("[orchestrator] bundled skills="
    + (loadBundledSkills ? (loadedSkillResources.skills.map((skill) => skill.name).join(",") || "none") : "disabled-for-speed"));
  for (const diagnostic of loadedSkillResources.diagnostics) {
    console.warn(`[orchestrator] skill diagnostic: ${diagnostic.message} path=${diagnostic.path}`);
  }

  const authStorage = AuthStorage.create(path.join(piRuntimeDir, "auth.json"));
  const modelRegistry = ModelRegistry.create(authStorage, modelsPath);
  const { providerId, model: resolvedModel } = resolvePiModel(authStorage, modelRegistry, modelConfig);
  const outputTokenLimit = Math.max(4_096, Math.min(65_536, Number(process.env.PI_MAX_MODEL_OUTPUT_TOKENS || "32768") || 32_768));
  const contextWindowLimit = Math.max(64_000, Math.min(512_000, Number(process.env.PI_MODEL_CONTEXT_WINDOW || "262144") || 262_144));
  const model = {
    ...resolvedModel,
    maxTokens: Math.min(resolvedModel.maxTokens, outputTokenLimit),
    contextWindow: Math.min(resolvedModel.contextWindow, contextWindowLimit),
  };
  console.log("[orchestrator] resolved provider=" + providerId
    + " model=" + model.id
    + " reasoning=" + Boolean(model.reasoning)
    + " context_window=" + model.contextWindow
    + " max_tokens=" + model.maxTokens);
  diagnostics.configureModel({ id: model.id, thinking: modelConfig.thinkingLevel, contextWindow: model.contextWindow, maxTokens: model.maxTokens });
  const createPiSession = async (tools = modelConfig.tools) => (await createAgentSession({
    cwd: outputDir,
    model,
    thinkingLevel: modelConfig.thinkingLevel,
    authStorage,
    modelRegistry,
    resourceLoader,
    sessionManager: SessionManager.inMemory(outputDir),
    tools,
  })).session;
  const initialSession = await createPiSession();

  const metrics = new ModelCallMetricsRecorder(outputDir, (metric) => diagnostics.modelCall(metric));
  const validationLogs = new ValidationLogCollector(outputDir);
  const implementationTimeoutMs = optionalPositiveEnv("PI_IMPLEMENTATION_TIMEOUT_MS")
    ?? (blueprintInstallation.application_seeded ? 40 * 60 * 1_000 : undefined);
  const repairTimeoutMs = optionalPositiveEnv("PI_REPAIR_TIMEOUT_MS")
    ?? (blueprintInstallation.application_seeded ? 10 * 60 * 1_000 : undefined);

  try {
    const store = new HandoffStore(outputDir);
    store.initialize(requirements.nodes);
    const graph = buildWorkGraph(requirements.nodes);
    let initialSessionAvailable = true;
    const sessionFactory = async () => {
      if (initialSessionAvailable) {
        initialSessionAvailable = false;
        return initialSession;
      }
      return createPiSession();
    };
    let generatedContracts = new Map<string, string>();
    const generateContracts = shouldGenerateRequirementContracts(
      hiddenTestMode,
      starterIsSubstantial,
      classification.level,
    );
    if (generateContracts) {
      console.log("[orchestrator] hidden minimal LARGE task: enabling independent requirement-derived contract verification"
        + " (set PI_GENERATE_CONTRACT_TESTS=0 to disable)");
      const packets = writeContractPackets(outputDir, parsedRequirements);
      const productSnapshot = snapshotProductSources(outputDir);
      const contractSession = await sessionFactory();
      try {
        metrics.beginStage("contract-test-authoring", "ARC-TASK");
        const unsubscribe = contractSession.subscribe((event) => {
          metrics.handleSessionEvent(event);
          const value = event as { type?: string; assistantMessageEvent?: { type?: string; delta?: string } };
          if (value.type === "message_update"
            && value.assistantMessageEvent?.type === "text_delta"
            && value.assistantMessageEvent.delta) process.stdout.write(value.assistantMessageEvent.delta);
        });
        try {
          await contractSession.prompt(buildContractTestPrompt(packets));
        } finally {
          unsubscribe();
        }
        generatedContracts = snapshotGeneratedContracts(outputDir);
        console.log("[orchestrator] generated independent contract files=" + generatedContracts.size);
      } catch (error) {
        console.warn("[orchestrator] contract-test authoring failed; continuing with browser smoke: "
          + (error instanceof Error ? error.message : String(error)));
        diagnostics.failure("contract-test-authoring", error);
      } finally {
        restoreProductSources(outputDir, productSnapshot);
        contractSession.dispose();
      }
    }

    const maxNodeRepairs = Math.max(0, Math.min(1, Number(process.env.PI_MAX_NODE_REPAIR_ROUNDS || "1")));
    const defaultNodeAttempts = blueprintInstallation.application_seeded ? 1 : 2;
    const maxNodeAttempts = Math.max(1, Math.min(3, Number(process.env.PI_MAX_NODE_ATTEMPTS || String(defaultNodeAttempts))));
    const summary = await runNodeSchedule({
      graph,
      store,
      sessionFactory,
      metrics,
      logs: validationLogs,
      stagedRequirementRoot: ".arc/requirements-source",
      maxRepairRounds: maxNodeRepairs,
      maxAttempts: maxNodeAttempts,
      promptTimeoutMs: implementationTimeoutMs,
      deadlineAt: pipelineDeadline,
      promptContext: {
        requirementSummary: requirementContext,
        testSummary: embeddedContext.testSummary,
        nodeDirectory: formatNodeDirectory(parsedRequirements.nodes, 6_000),
        starterSnapshot: buildStarterSnapshot(outputDir, 12_000, starterIsSubstantial),
        preparedCapabilities: preparedCapabilityContext,
        hasPublicTests: publicTests.length > 0,
        starterIsSubstantial,
        applicationSeeded: blueprintInstallation.application_seeded,
        globalContract: parsedRequirements.globalContract,
        hasGeneratedContracts: generatedContracts.size > 0,
      },
      lifecycle: {
        beginNode(node, attempt) {
          diagnostics.beginNode(node, attempt);
          return runtimeReporter.beginNode(node, attempt);
        },
        completeNode(node, handoff) {
          runtimeReporter.completeNode(node, handoff);
          diagnostics.completeNode(node, handoff);
        },
        failNode(node, message, recentAssistantText) {
          runtimeReporter.failNode(node, message);
          diagnostics.failNode(node, message, recentAssistantText);
        },
        blockNode(node, message) {
          runtimeReporter.blockNode(node, message);
          diagnostics.blockNode(node, message);
        },
        restoreCheckpoint(commitOid) {
          runtimeReporter.restoreCheckpoint(commitOid);
        },
      },
    });
    if (summary.failed.length || summary.blocked.length) {
      console.warn("[orchestrator] implementation incomplete; validating preserved output. failed="
        + summary.failed.join(",") + " blocked=" + summary.blocked.join(","));
    }
    let finalValidation = await validateProject(outputDir, "final-diagnostic", pipelineDeadline, "diagnostic");
    diagnostics.validation("final-diagnostic", finalValidation.passed, finalValidation.durationMs, finalValidation.result);
    const finalRepairRounds = Math.max(0, Math.min(3, Number(process.env.PI_MAX_REPAIR_ROUNDS || "3")));
    let sharedRepairSession: Awaited<ReturnType<typeof createPiSession>> | undefined;
    try {
      for (let round = 1; !finalValidation.passed && round <= finalRepairRounds; round += 1) {
        const remainingMs = pipelineDeadline === undefined ? undefined : pipelineDeadline - Date.now();
        if (remainingMs !== undefined && remainingMs <= 0) {
          console.warn("[orchestrator] skipping repair to honor the total time budget; preserving output for evaluation");
          break;
        }
        try {
          sharedRepairSession ||= await createPiSession(modelConfig.tools.filter((tool) => tool !== "bash"));
          await runRepairSession({
            sessionFactory: () => createPiSession(modelConfig.tools.filter((tool) => tool !== "bash")),
            session: sharedRepairSession,
            validation: finalValidation.result,
            round,
            metrics,
            logs: validationLogs,
            timeoutMs: remainingMs === undefined
              ? repairTimeoutMs
              : Math.min(repairTimeoutMs || remainingMs, remainingMs),
            hasPublicTests: publicTests.length > 0,
          });
          restoreGeneratedContracts(generatedContracts);
        } catch (error) {
          sharedRepairSession?.dispose();
          sharedRepairSession = undefined;
          console.warn(`[orchestrator] repair session ${round} failed; preserving output: ${error instanceof Error ? error.message : String(error)}`);
          diagnostics.failure(`repair-${round}`, error);
        }
        // Keep early feedback cheap, but expose the complete remaining failure set
        // before the last repair so hidden tail failures still get one fix attempt.
        const validationMode = round < finalRepairRounds - 1 ? "diagnostic" : "full";
        finalValidation = await validateProject(outputDir, `final-repair-${round}`, pipelineDeadline, validationMode);
        diagnostics.validation(`final-repair-${round}`, finalValidation.passed, finalValidation.durationMs, finalValidation.result);
      }
    } finally {
      sharedRepairSession?.dispose();
    }
    if (finalValidation.passed) {
      for (const node of requirements.nodes) {
        if (store.load(node.id)?.status === "IMPLEMENTED") store.setStatus(node.id, "PASSED");
      }
      console.log("[orchestrator] "
        + (hiddenTestMode ? "runtime smoke PASS" : "public-contract validation PASS")
        + " in " + finalValidation.durationMs + "ms");
      runtimeReporter.finalize(true, "Implementation and validation passed.");
      diagnostics.finalize(true, "Implementation and validation passed.");
    } else {
      console.warn("[orchestrator] validation warnings remain; preserving output for ARC-Bench evaluation. "
        + finalValidation.result.primary_error + " log=" + (finalValidation.result.raw_log_path || "none"));
      runtimeReporter.finalize(false, `Validation warnings remain: ${finalValidation.result.primary_error}`);
      diagnostics.finalize(false, `Validation warnings remain: ${finalValidation.result.primary_error}`, true);
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("[orchestrator] non-fatal generation error; preserving workspace for ARC-Bench evaluation: " + message);
    runtimeReporter.finalize(false, "Partial output preserved after generation error: " + message);
    diagnostics.failure("generation", error);
    diagnostics.finalize(false, "Partial output preserved after generation error: " + message, true);
  } finally {
    cleanupGeneratedContracts(outputDir);
    const evaluationState = prepareEvaluationState(outputDir, pipelineDeadline);
    if (evaluationState.ok) {
      console.log("[orchestrator] restored clean evaluation database state");
    } else {
      console.warn("[orchestrator] could not restore evaluation database state: " + evaluationState.output);
      diagnostics.failure("evaluation-state", evaluationState.output);
    }
    if (stagedPublicTests && fs.existsSync(stagedPublicTests)) {
      fs.rmSync(stagedPublicTests, { recursive: true, force: true });
      console.log("[orchestrator] removed staged public tests; /workspace/tests was never modified");
    }
    initialSession.dispose();
    for (const [signal, handler] of signalHandlers) process.off(signal, handler);
  }
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));
  const requirementsDir = path.resolve(args.requirementPath);
  const outputDir = path.resolve(args.outputDir);
  const runtime = AgentRuntime.fromEnv({ projectDir: outputDir });
  try {
    await runAgent(runtime, requirementsDir, outputDir, args.taskType);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    runtime.events.markRunFailed(`Agent startup failed: ${message}`);
    throw error;
  }
}

main().catch((error: unknown) => {
  console.error(error);
  process.exit(1);
});
# Generic requirement-driven orchestration

Every task follows the same pipeline:

1. Parse all supplied requirement files into a dependency graph.
2. Preserve a supplied starter project and summarize its source inventory before editing.
3. Retain root-level data/fixture contracts and complete per-node requirement details.
4. With public tests, use their executable contracts. Without public tests, spend the default model budget on implementation packages; optional model-authored contract tests require explicit opt-in.
5. Install a strongly matched prepared application when available; otherwise implement incrementally from capability foundations. The final package performs a focused cross-module closure audit.
6. Run deterministic build, unit, staged E2E, or real-browser runtime-smoke validation against an isolated database.
7. Reuse one evidence-driven repair session across up to three validation rounds when validation fails.
8. Publish requirement, scenario, interface, test, node-state, and run-state changes through the ArcBench Runtime SDK.
9. Commit each successful implementation package. Before a fresh retry, restore the last package-start checkpoint so a failed attempt cannot poison later work.
10. Preserve the workspace for benchmark evaluation even if internal validation still reports failures.

Work state is stored under `.arc/work-nodes/`. Passed work is resumable, failed model calls retry in a fresh session, and full validation logs are stored under `.arc/logs/`.

Environment controls:

```sh
PI_MAX_WORK_SESSIONS=1..8
PI_MAX_NODE_ATTEMPTS=1..3
PI_MAX_NODE_REPAIR_ROUNDS=0..1
PI_MAX_REPAIR_ROUNDS=0..3
PI_LOAD_BUNDLED_SKILLS=0
PI_PREPARE_BLUEPRINTS=1
PI_PREPARED_APP_SESSIONS=1..4
PI_MAX_MODEL_OUTPUT_TOKENS=32768
PI_MODEL_CONTEXT_WINDOW=262144
PI_ARCBENCH_RUNTIME=1
PI_ARCBENCH_OFFICIAL_SDK=1
PI_ROLLBACK_FAILED_ATTEMPTS=1
PI_AUTO_THINKING=1
PI_THINKING_LEVEL=low|medium|high  # explicit value overrides automatic medium
PI_GENERATE_CONTRACT_TESTS=0  # set 1 only for an explicit model-authored diagnostic suite
PI_BROWSER_EXECUTABLE=<optional Chrome/Chromium path>
PI_IMPLEMENTATION_TIMEOUT_MS=<optional explicit milliseconds>
PI_TOTAL_BUDGET_MS=<optional explicit milliseconds>
PI_REPAIR_TIMEOUT_MS=<optional explicit milliseconds>
```

The defaults prioritize minimal discovery when public tests exist, and semantic feature-package coverage when only hidden tests are available.

The orchestrator has no default wall-clock cutoff. Time limits are applied only when the corresponding environment variable is explicitly supplied.

ArcBench's built-in Python SDK is called in batches to avoid one Python process per requirement. If that package is unavailable during local development, the bundled JavaScript runtime writes the same traceability tables and checkpoint signals without stopping generation.
# ARC-Bench Pi Agent v5.7

This package is an ARC-Bench submission folder based on the TypeScript starter, adapted to run Pi through a thin SDK-based adapter in `index.ts`.

ARC-Bench runs the agent like this:

```bash
tsx index.ts /path/to/requirements --output-dir /path/to/output --type web
```

What this package does:

1. Preserves the task-provided starter project byte-for-byte; the bundled scaffold is installed only when the output directory has no project markers.
2. Creates a local Pi runtime config from `OPENAI_API_KEY`, `OPENAI_BASE_URL`, and `MODEL`.
3. Starts Pi with its SDK in --output-dir. Large hidden-test tasks keep deepseek-v4-flash and automatically raise its thinking level from low to medium unless PI_THINKING_LEVEL is explicitly set. Set PI_THINKING_LEVEL=high for maximum reasoning or PI_AUTO_THINKING=0 to preserve low.
4. Prompts Pi to read the ARC requirements and implement the task in place.
5. Keeps the implementation-first strategy for substantial starters. Model-authored contract suites are off by default after benchmark evidence showed high cost and weak alignment; set `PI_GENERATE_CONTRACT_TESTS=1` only for an explicit diagnostic run.
6. Uses compact public-test-driven sessions when tests exist. Unprepared hidden-test work can use up to six semantic packages. The prepared GitHub application uses two audit/repair sessions by default, while the already stronger spreadsheet application uses one (`PI_PREPARED_APP_SESSIONS` overrides either default).
7. Detects reusable capabilities from the requirement graph and, for an empty bundled scaffold, installs tested blueprint foundations before model work. The model receives a manifest and is instructed to configure and extend those files instead of regenerating infrastructure.
8. Preserves root-level YAML data/fixture obligations plus every assigned description and scenario without character clipping in hidden-test packages.
9. Includes two requirement-selected application starters derived from prior benchmark outputs: repository collaboration and spreadsheet workspace. They are installed only over the package's own empty scaffold and never over a supplied user starter.
10. Runs deterministic build/runtime validation against disposable databases and restores a clean seeded database before official evaluation. Generated contract suites run only when explicitly requested.
11. Uses the official `arcbench_agent_runtime` Python SDK through a batched TypeScript bridge when it is available. Requirements, scenarios, generated interfaces, tests, per-node states, and run completion are published through high-level SDK calls; the bundled JavaScript implementation is only an offline compatibility fallback.
12. Creates a Git checkpoint after every successful semantic package. A retry restores the package-start checkpoint and removes files created by the failed attempt, while terminal failures keep their partial output for evaluation.
13. Preinstalls frontend/backend dependencies before auditing a prepared application. Audit sessions must execute the real seed, build, and focused API/browser flows; static syntax or source review alone is not accepted as verification. Set `PI_PREINSTALL_PREPARED_APP=0` only to diagnose dependency installation itself.

The same pipeline handles every requirement set. Domain behavior must come from the supplied YAML, tests, and project files.

The complete generation pipeline has a default 90-minute wall-clock budget, starting before prepared-application dependency installation and covering model work, retries, build/runtime validation, and repair. Override it with `PI_TOTAL_BUDGET_MS`. Prepared applications additionally default to 40 minutes per implementation session and 10 minutes per repair session; override those limits with `PI_IMPLEMENTATION_TIMEOUT_MS` and `PI_REPAIR_TIMEOUT_MS`.

Prepared applications use one model attempt per work package by default. A truncated stream therefore preserves partial edits and proceeds to deterministic validation instead of starting another full audit while an earlier server may still be alive. Set `PI_MAX_NODE_ATTEMPTS=2` only when retrying is worth the additional budget.

`vendor/earendil-works-pi-coding-agent-0.74.0.tgz` is included so the submission folder carries the Pi package with it instead of depending on a live npm lookup for that package name.

This package intentionally uses Pi `0.74.0` because it has a lower Node.js requirement than newer Pi releases and is a better fit for ARC-Bench's current TypeScript runner environment.

Runtime integration can be disabled with `PI_ARCBENCH_RUNTIME=0`. Set `PI_ARCBENCH_OFFICIAL_SDK=0` only for local/offline testing. Failed-attempt rollback is enabled by default and can be disabled with `PI_ROLLBACK_FAILED_ATTEMPTS=0`.

DeepSeek output is capped at 32,768 tokens and its advertised context window at 262,144 tokens by default. Override with `PI_MAX_MODEL_OUTPUT_TOKENS` and `PI_MODEL_CONTEXT_WINDOW` only when a task proves it needs more.

