29:export function listRelativeFiles(rootDir: string, maxDepth = 2): string[] {
30:  const results: string[] = [];
31:  if (!fs.existsSync(rootDir) || !fs.statSync(rootDir).isDirectory()) return results;
32:
33:  function walk(currentDir: string, depth: number): void {
34:    if (depth > maxDepth) return;
35:    const entries = fs.readdirSync(currentDir, { withFileTypes: true })
36:      .filter((entry) => !entry.name.startsWith("."))
37:      .sort((a, b) => a.name.localeCompare(b.name));
38:    for (const entry of entries) {
39:      const absolutePath = path.join(currentDir, entry.name);
40:      const relativePath = path.relative(rootDir, absolutePath) || ".";
41:      if (entry.isDirectory()) {
42:        results.push(`${relativePath}/`);
43:        walk(absolutePath, depth + 1);
44:      } else if (entry.isFile()) {
45:        results.push(relativePath);
46:      }
47:    }
48:  }
49:
50:  walk(rootDir, 0);
51:  return results;
52:}
