54:function clipWithNotice(text: string, budget: number, label: string): { text: string; truncated: boolean } {
55:  if (text.length <= budget) return { text, truncated: false };
56:  const notice = `\n...[${label} truncated; use the read tool to open the source file]`;
57:  return { text: `${text.slice(0, Math.max(0, budget - notice.length))}${notice}`, truncated: true };
58:}
