79:export function buildRequirementSummary(requirementsDir: string, budget = CONTEXT_BUDGETS.requirements): string {
80:  const files = requirementCandidates(requirementsDir);
81:  const directory = files.map((file) => `- ${file}`).join("\n") || "- none";
82:  const sections = [`Requirement file directory (always retained):\n${directory}`];
83:  let remaining = budget - sections[0].length - 2;
84:
85:  for (const relativeFile of files) {
86:    if (remaining <= 0) break;
87:    const absolutePath = path.join(requirementsDir, relativeFile);
88:    const source = fs.readFileSync(absolutePath, "utf8").trim();
89:    if (!source) continue;
90:    const header = `File: ${relativeFile}\n`;
91:    if (header.length >= remaining) break;
92:    const clipped = clipWithNotice(source, remaining - header.length, relativeFile);
93:    sections.push(`${header}${clipped.text}`);
94:    remaining -= header.length + clipped.text.length + 2;
95:    if (clipped.truncated) break;
96:  }
97:
98:  if (sections.length === 1) {
99:    sections.push("No readable requirement text was embedded. Use the read tool on the listed files.");
100:  } else if (files.length > sections.length - 1) {
101:    sections.push("...[additional requirement files omitted; use the read tool and directory above]");
102:  }
103:  return clipWithNotice(sections.join("\n\n"), budget, "requirements").text;
104:}
