122:function deriveHelperTimingContract(source: string): string {
123:  if (!/firstVisible|isVisible\s*\(/.test(source)) return "";
124:  const functionNames = ["clickNamed", "expectTextsVisible", "expectVisible"];
125:  const positions = functionNames
126:    .map((name) => ({
127:      name,
128:      start: source.search(new RegExp(`(?:function|const)\\s+${name}\\b`)),
129:    }))
130:    .filter((item) => item.start >= 0)
131:    .sort((left, right) => left.start - right.start);
132:  const contracts: string[] = [];
133:  for (let index = 0; index < positions.length; index += 1) {
134:    const { name, start } = positions[index];
135:    const end = Math.min(positions[index + 1]?.start ?? source.length, start + 3_000);
136:    const excerpt = source.slice(start, end);
137:    const locators = [...excerpt.matchAll(/getBy(Role|Text|Placeholder)\(\s*(?:["']([^"']+)["'])?/g)]
138:      .map((match) => match[1] === "Role" ? `role(${match[2] || "dynamic"})` : match[1].toLowerCase())
139:      .slice(0, 8);
140:    if (locators.length) {
141:      contracts.push(`- ${name}: ordered locators ${locators.join(" -> ")}; when none is visible immediately, assume the first locator remains the fallback.`);
142:    }
143:  }
144:  if (!contracts.length) return "";
145:  return [
146:    "Derived asynchronous-locator contract:",
147:    ...contracts,
148:    "- Async-loaded click targets must eventually match the fallback role, not merely a later candidate role.",
149:    "- Preserve a compatible accessible role/name across route transitions when the next assertion can begin before navigation commits.",
150:    "- A robust named interactive item can be a real button containing a heading with the same exact accessible name; post-action labels asserted as headings need an actual heading node.",
151:  ].join("\n");
152:}
