154:export function buildImplementationBrief(requirements: RequirementSet, budget = CONTEXT_BUDGETS.requirements): string {
155:  const sections = requirements.nodes.map((node) => {
156:    const lines = [`${node.id} | ${node.name} | ${node.type}`];
157:    if (node.parentId) lines.push(`Parent: ${node.parentId}`);
158:    if (node.dependencies.length) lines.push(`Depends: ${node.dependencies.join(", ")}`);
159:    if (node.description) lines.push(`Requirement: ${oneLine(node.description)}`);
160:    for (const scenario of node.scenarios) {
161:      const criteria = scenario.acceptanceCriteria.length
162:        ? ` | Accept: ${scenario.acceptanceCriteria.map(oneLine).join("; ")}`
163:        : "";
164:      lines.push(`Scenario: ${oneLine(scenario.name)} | ${oneLine(scenario.description)}${criteria}`);
165:    }
166:    return lines.join("\n");
167:  });
168:  const brief = sections.join("\n\n") || "No structured requirements were parsed; inspect the staged requirement source.";
169:  return clipWithNotice(brief, budget, "implementation brief").text;
170:}
