160:function requirementCorpus(requirements: RequirementSet): string {
161:  return [
162:    requirements.globalContract || "",
163:    ...requirements.nodes.flatMap((node) => [
164:      node.name,
165:      node.description,
166:      ...node.scenarios.flatMap((scenario) => [scenario.name, scenario.description, ...scenario.acceptanceCriteria]),
167:    ]),
168:  ].join("\n");
169:}
170:
171:export function detectCapabilities(requirements: RequirementSet): CapabilityMatch[] {
172:  const corpus = requirementCorpus(requirements);
173:  const matches = CAPABILITY_CATALOG.map((definition): CapabilityMatch => {
174:    let score = 0;
175:    const evidence: string[] = [];
176:    for (const candidate of definition.signals) {
177:      candidate.pattern.lastIndex = 0;
178:      if (!candidate.pattern.test(corpus)) continue;
179:      score += candidate.weight;
180:      evidence.push(candidate.label);
181:    }
182:    return {
183:      id: definition.id,
184:      description: definition.description,
185:      score,
186:      evidence: [...new Set(evidence)],
187:      selected: definition.id === "web-kernel" || score >= definition.threshold,
188:    };
189:  });
190:
191:  const selected = new Set(matches.filter((match) => match.selected).map((match) => match.id));
192:  const addDependencies = (id: CapabilityId): void => {
193:    const definition = CAPABILITY_CATALOG.find((item) => item.id === id);
194:    for (const dependency of definition?.dependencies || []) {
195:      if (!selected.has(dependency)) {
196:        selected.add(dependency);
197:        addDependencies(dependency);
198:      }
199:    }
200:  };
201:  for (const id of [...selected]) addDependencies(id);
202:  return matches.map((match) => ({ ...match, selected: selected.has(match.id) }));
203:}
204:
205:export function capabilityDefinition(id: CapabilityId): CapabilityDefinition {
206:  const definition = CAPABILITY_CATALOG.find((item) => item.id === id);
207:  if (!definition) throw new Error(`Unknown blueprint capability: ${id}`);
208:  return definition;
209:}
