1:import fs from "node:fs";
2:import path from "node:path";
3:
4:import { capabilityDefinition, type CapabilityId, type CapabilityMatch } from "./catalog.js";
5:
6:export type PreparedCapability = {
7:  id: CapabilityId;
8:  description: string;
9:  score: number;
10:  evidence: string[];
11:  installed_files: string[];
12:  existing_files: string[];
13:  replaced_files: string[];
14:};
15:
16:export type BlueprintInstallation = {
17:  version: 1;
18:  mode: "installed" | "manifest-only" | "disabled";
19:  generated_at: string;
20:  application_seeded: boolean;
21:  capabilities: PreparedCapability[];
22:};
23:
24:function copyBlueprintFiles(sourceRoot: string, outputDir: string, overwriteExisting = false): { installed: string[]; existing: string[]; replaced: string[] } {
25:  const installed: string[] = [];
26:  const existing: string[] = [];
27:  const replaced: string[] = [];
28:  if (!fs.existsSync(sourceRoot)) return { installed, existing, replaced };
29:
30:  const visit = (directory: string): void => {
31:    for (const entry of fs.readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
32:      if (entry.name.startsWith(".")) continue;
33:      const source = path.join(directory, entry.name);
34:      if (entry.isDirectory()) {
35:        visit(source);
36:        continue;
37:      }
38:      if (!entry.isFile()) continue;
39:      const relative = path.relative(sourceRoot, source);
40:      const destination = path.join(outputDir, relative);
41:      if (fs.existsSync(destination)) {
42:        if (overwriteExisting) {
43:          fs.copyFileSync(source, destination);
44:          replaced.push(relative);
45:          continue;
46:        }
47:        existing.push(relative);
48:        continue;
49:      }
50:      fs.mkdirSync(path.dirname(destination), { recursive: true });
51:      fs.copyFileSync(source, destination, fs.constants.COPYFILE_EXCL);
52:      installed.push(relative);
53:    }
54:  };
55:  visit(sourceRoot);
56:  return { installed, existing, replaced };
57:}
58:
59:export function prepareCapabilities(options: {
60:  matches: CapabilityMatch[];
61:  blueprintsDir: string;
62:  outputDir: string;
63:  installFiles: boolean;
64:  enabled?: boolean;
65:}): BlueprintInstallation {
66:  const enabled = options.enabled !== false;
67:  const selected = options.matches.filter((match) => match.selected);
68:  const capabilities = selected.map((match): PreparedCapability => {
69:    const definition = capabilityDefinition(match.id);
70:    const copied = enabled && options.installFiles
71:      ? copyBlueprintFiles(
72:        path.join(options.blueprintsDir, match.id, "files"),
73:        options.outputDir,
74:        definition.overwriteBundledScaffold === true,
75:      )
76:      : { installed: [], existing: [], replaced: [] };
77:    return {
78:      id: match.id,
79:      description: definition.description,
80:      score: match.score,
81:      evidence: match.evidence,
82:      installed_files: copied.installed,
83:      existing_files: copied.existing,
84:      replaced_files: copied.replaced,
85:    };
86:  });
87:  const installation: BlueprintInstallation = {
88:    version: 1,
89:    mode: !enabled ? "disabled" : options.installFiles ? "installed" : "manifest-only",
90:    generated_at: new Date().toISOString(),
91:    application_seeded: enabled && options.installFiles && capabilities.some((capability) =>
92:      capabilityDefinition(capability.id).overwriteBundledScaffold === true
93:      && capability.installed_files.length + capability.replaced_files.length > 0),
94:    capabilities,
95:  };
96:  const manifestPath = path.join(options.outputDir, ".arc", "prepared-capabilities.json");
97:  fs.mkdirSync(path.dirname(manifestPath), { recursive: true });
98:  fs.writeFileSync(manifestPath, JSON.stringify(installation, null, 2), "utf8");
99:  return installation;
100:}
101:
102:export function formatPreparedCapabilities(installation: BlueprintInstallation): string {
103:  if (!installation.capabilities.length) return "No reusable capability blueprints were selected.";
104:  const lines = installation.capabilities.map((capability) => {
105:    const files = [...capability.installed_files, ...capability.replaced_files, ...capability.existing_files];
106:    const preview = files.slice(0, 20);
107:    const omitted = Math.max(0, files.length - preview.length);
108:    return [
109:      `- ${capability.id}: ${capability.description}`,
110:      `  Evidence: ${capability.evidence.join(", ") || "base web runtime"}`,
111:      `  Reusable files: ${preview.join(", ") || "manifest only"}${omitted ? `, ... (${omitted} more)` : ""}`,
112:    ].join("\n");
113:  });
114:  return [
115:    `Blueprint mode: ${installation.mode}`,
116:    ...lines,
117:    "Reuse and adapt these files instead of regenerating equivalent infrastructure. They are foundations, not proof that product requirements are complete; audit each assigned requirement and wire the selected helpers into the real application.",
118:  ].join("\n");
119:}
