38:function assistantText(session: SessionLike): string {
39:  return (session.state.messages || [])
40:    .filter((message) => (message as { role?: string }).role === "assistant")
41:    .map((message) => {
42:      const content = (message as { content?: unknown }).content;
43:      if (typeof content === "string") return content;
44:      if (!Array.isArray(content)) return "";
45:      return content.map((item) => {
46:        const block = item as { type?: string; text?: string };
47:        return block.type === "text" && block.text ? block.text : "";
48:      }).join("\n");
49:    }).join("\n");
50:}
