67:async function abortSession(session: SessionLike): Promise<void> {
68:  if (!session.abort) return;
69:  let timer: ReturnType<typeof setTimeout> | undefined;
70:  try {
71:    await Promise.race([
72:      session.abort().catch(() => undefined),
73:      new Promise<void>((resolve) => { timer = setTimeout(resolve, 2_000); }),
74:    ]);
75:  } finally {
76:    if (timer) clearTimeout(timer);
77:  }
78:}
