80:async function safePrompt(
81:  session: SessionLike,
82:  prompt: string,
83:  metrics: ModelCallMetricsRecorder,
84:  timeoutMs?: number,
85:): Promise<void> {
86:  let timer: ReturnType<typeof setTimeout> | undefined;
87:  try {
88:    const execution = session.prompt(prompt);
89:    if (timeoutMs && timeoutMs > 0) {
90:      await Promise.race([
91:        execution,
92:        new Promise<never>((_resolve, reject) => {
93:          timer = setTimeout(() => {
94:            const message = `Model implementation timed out after ${timeoutMs}ms; partial files were preserved.`;
95:            if (session.abort) void session.abort().catch(() => undefined);
96:            reject(new Error(message));
97:          }, timeoutMs);
98:        }),
99:      ]);
100:    } else {
101:      await execution;
102:    }
103:  } catch (error) {
104:    // A truncated streaming response can reject while a model-started shell tool
105:    // is still active. Abort before disposing the session so its foreground tool
106:    // and descendants receive cancellation instead of leaking into a retry.
107:    await abortSession(session);
108:    metrics.recordFailure(error);
109:    throw error;
110:  } finally {
111:    if (timer) clearTimeout(timer);
112:  }
113:  if (session.state.errorMessage) throw new Error(session.state.errorMessage);
114:}
