116:export async function runNodeSchedule(options: {
117:  graph: WorkGraph;
118:  store: HandoffStore;
119:  sessionFactory: () => Promise<SessionLike>;
120:  metrics: ModelCallMetricsRecorder;
121:  logs: ValidationLogCollector;
122:  stagedRequirementRoot: string;
123:  maxRepairRounds: number;
124:  maxAttempts?: number;
125:  promptContext?: NodePromptContext;
126:  promptTimeoutMs?: number;
127:  deadlineAt?: number;
128:  lifecycle?: NodeLifecycle;
129:}): Promise<NodeRunSummary> {
130:  const { graph, store, sessionFactory, metrics, logs, stagedRequirementRoot, maxRepairRounds } = options;
131:  const maxAttempts = Math.max(1, Math.min(3, Math.floor(options.maxAttempts ?? 1)));
132:  const retryNode = process.env.PI_RETRY_NODE?.trim();
133:  const passed: string[] = [];
134:  const failed: string[] = [];
135:  const blocked: string[] = [];
136:
137:  for (const nodeId of graph.order) {
138:    const node = graph.byId.get(nodeId)!;
139:    const previous = store.load(nodeId)!;
140:    if (["PASSED", "IMPLEMENTED"].includes(previous.status) && retryNode !== nodeId) {
141:      passed.push(nodeId);
142:      console.log(`[orchestrator] node=${nodeId} status=${previous.status} action=resume-skip`);
143:      continue;
144:    }
145:    if (previous.status === "FAILED" && retryNode !== nodeId && previous.attempts >= maxAttempts) {
146:      failed.push(nodeId);
147:      console.log(`[orchestrator] node=${nodeId} status=FAILED action=skip; set PI_RETRY_NODE=${nodeId} to retry`);
148:      continue;
149:    }
150:    const dependencyStates = node.dependencies.map((id) => store.load(id));
151:    if (dependencyStates.some((item) => !item || !["PASSED", "IMPLEMENTED"].includes(item.status))) {
152:      const message = "Dependency implementation is incomplete.";
153:      store.setStatus(nodeId, "BLOCKED", { known_issues: [message] });
154:      options.lifecycle?.blockNode(node, message);
155:      blocked.push(nodeId);
156:      continue;
157:    }
158:
159:    const attemptLimit = retryNode === nodeId ? previous.attempts + maxAttempts : maxAttempts;
160:    let previousFailure = previous.known_issues.at(-1) || "The previous session did not complete.";
161:    let nodeComplete = false;
162:    for (let attempt = previous.attempts + 1; attempt <= attemptLimit && !nodeComplete; attempt += 1) {
163:      store.setStatus(nodeId, "RUNNING", { attempts: attempt });
164:      const checkpoint = options.lifecycle?.beginNode(node, attempt) || null;
165:      let session: SessionLike | undefined;
166:      try {
167:        session = await sessionFactory();
168:        bindSession(session, metrics, logs);
169:        metrics.beginStage(attempt === 1 ? "node-implementation" : `node-recovery-${attempt}`, nodeId);
170:        const prompt = attempt === 1
171:          ? buildNodePrompt(node, store.dependencySummaries(node), stagedRequirementRoot, options.promptContext)
172:          : buildNodeRetryPrompt(node, store.dependencySummaries(node), stagedRequirementRoot, previousFailure, options.promptContext);
173:        const remainingMs = options.deadlineAt ? options.deadlineAt - Date.now() : undefined;
174:        if (remainingMs !== undefined && remainingMs <= 0) {
175:          throw new Error("Total pipeline time budget exhausted before implementation completed.");
176:        }
177:        const implementationTimeout = remainingMs === undefined
178:          ? options.promptTimeoutMs
179:          : Math.min(options.promptTimeoutMs || remainingMs, remainingMs);
180:        await safePrompt(session, prompt, metrics, implementationTimeout);
181:        let validation = logs.flush(`${nodeId}-attempt-${attempt}`);
182:        for (let round = 1; !nodePassed(session) && round <= maxRepairRounds; round += 1) {
183:          store.setStatus(nodeId, "VALIDATING");
184:          metrics.beginStage(`node-completion-${round}`, nodeId);
185:          const completionRemainingMs = options.deadlineAt ? options.deadlineAt - Date.now() : undefined;
186:          if (completionRemainingMs !== undefined && completionRemainingMs <= 0) throw new Error("Total pipeline time budget exhausted before completion handoff.");
187:          await safePrompt(session, buildNodeCompletionPrompt(node), metrics, completionRemainingMs);
188:          validation = logs.flush(`${nodeId}-attempt-${attempt}-completion-${round}`);
189:        }
190:        const output = assistantText(session);
191:        const handoff = extractHandoff(output);
192:        if (!nodePassed(session)) {
193:          throw new Error(`Session ended without NODE_STATUS: IMPLEMENTED. ${validation.primary_error}`);
194:        }
195:        const completedHandoff = store.setStatus(nodeId, "IMPLEMENTED", handoff);
196:        options.lifecycle?.completeNode(node, completedHandoff);
197:        passed.push(nodeId);
198:        nodeComplete = true;
199:      } catch (error) {
200:        previousFailure = error instanceof Error ? error.message : String(error);
201:        logs.flush(`${nodeId}-attempt-${attempt}-error`);
202:        const timedOut = /timed out/i.test(previousFailure);
203:        const willRetry = attempt < attemptLimit && !timedOut;
204:        console.error(`[orchestrator] node=${nodeId} attempt=${attempt}/${attemptLimit} error=${previousFailure}${willRetry ? " action=retry-fresh-session" : " action=preserve-and-validate"}`);
205:        options.lifecycle?.failNode(node, previousFailure, session ? assistantText(session).slice(-4_000) : "");
206:        if (willRetry) options.lifecycle?.restoreCheckpoint(checkpoint);
207:        store.setStatus(nodeId, willRetry ? "PENDING" : "FAILED", { known_issues: [previousFailure] });
208:        if (!willRetry) {
209:          failed.push(nodeId);
210:          nodeComplete = true;
211:        }
212:      } finally {
213:        session?.dispose();
214:      }
215:    }
216:  }
217:
218:  for (const nodeId of graph.order) {
219:    if (store.load(nodeId)?.status === "BLOCKED" && !blocked.includes(nodeId)) blocked.push(nodeId);
220:  }
221:  return { passed, failed, blocked };
222:}
