119:function waitForHealth(port: number, timeoutMs: number): Promise<boolean> {
120:  const deadline = Date.now() + timeoutMs;
121:  return new Promise((resolve) => {
122:    const attempt = (): void => {
123:      const request = http.get(`http://127.0.0.1:${port}/api/health`, (response) => {
124:        response.resume();
125:        if ((response.statusCode || 500) >= 200 && (response.statusCode || 500) < 300) resolve(true);
126:        else if (Date.now() >= deadline) resolve(false);
127:        else setTimeout(attempt, 250);
128:      });
129:      request.on("error", () => Date.now() >= deadline ? resolve(false) : setTimeout(attempt, 250));
130:      request.setTimeout(1_000, () => request.destroy());
131:    };
132:    attempt();
133:  });
134:}
