161:async function stopServer(server: ReturnType<typeof spawn>): Promise<void> {
162:  if (server.exitCode !== null || server.signalCode !== null) return;
163:  await new Promise<void>((resolve) => {
164:    const forceTimer = setTimeout(() => {
165:      if (server.exitCode === null && server.signalCode === null) server.kill("SIGKILL");
166:    }, 2_000);
167:    const done = (): void => {
168:      clearTimeout(forceTimer);
169:      resolve();
170:    };
171:    server.once("exit", done);
172:    server.kill("SIGTERM");
173:    setTimeout(done, 3_000);
174:  });
