179:  deadlineAt?: number,
180:  mode: ValidationMode = "full",
181:): Promise<{ ok: boolean; output: string; command?: ValidationCommand }> {
182:  const backend = path.join(outputDir, "backend");
183:  const staged = path.join(backend, "test-e2e", ".arcbench-public");
184:  const hasPublicE2E = hasTestFiles(staged);
185:  const generatedCount = generatedContractCount(outputDir);
186:  if (!fs.existsSync(path.join(backend, "src", "index.js"))) {
187:    return { ok: true, output: "No backend runtime entrypoint; skipped server smoke validation." };
188:  }
189:  if (budgetExpired(deadlineAt)) return { ok: false, output: "Total pipeline time budget exhausted before E2E validation." };
190:  const validationDbDir = path.join(outputDir, ".arc", "validation-db");
191:  fs.mkdirSync(validationDbDir, { recursive: true });
192:  const validationDbPath = path.join(validationDbDir, `${mode}-${process.pid}-${Date.now()}.sqlite`);
193:  removeSqliteArtifacts(validationDbPath);
194:  const isolatedEnv = { ...process.env, CI: "1", ARC_DB_FILE: validationDbPath, DATABASE_FILE: validationDbPath };
195:  let preparationOutput = "";
196:  if (packageScript(backend, "db:prepare:e2e")) {
197:    const preparation = spawnSync("npm", ["run", "db:prepare:e2e"], {
198:      cwd: backend,
199:      encoding: "utf8",
200:      timeout: remainingTimeout(120_000, deadlineAt),
201:      env: isolatedEnv,
202:      maxBuffer: 4 * 1024 * 1024,
203:    });
204:    preparationOutput = [preparation.stdout || "", preparation.stderr || ""].join("\n");
205:    if (preparation.status !== 0 || preparation.error) {
206:      removeSqliteArtifacts(validationDbPath);
207:      return { ok: false, output: `Isolated E2E database preparation failed.\n${preparationOutput}` };
208:    }
209:  }
210:  const port = 34_000 + ((process.pid + Date.now()) % 1_000);
211:  const server = spawn(process.execPath, ["src/index.js"], {
212:    cwd: backend, env: { ...isolatedEnv, PORT: String(port), ARC_WEB_PORT: String(port) },
213:    stdio: ["ignore", "pipe", "pipe"], detached: false,
214:  });
215:  let serverOutput = "";
216:  server.stdout?.on("data", (chunk) => { serverOutput += String(chunk); });
217:  server.stderr?.on("data", (chunk) => { serverOutput += String(chunk); });
218:  const command: ValidationCommand = { stage: "E2E_TEST", cwd: backend, command: "npx", args: buildE2EArgs(mode), timeoutMs: 180_000 };
219:  try {
220:    if (!await waitForHealth(port, remainingTimeout(15_000, deadlineAt))) return { ok: false, output: `${serverOutput}\nServer health check failed.`, command };
221:    if (!hasPublicE2E) {
222:      installBrowserSmoke(outputDir);
223:      const args = ["playwright", "test", "--config=playwright.contract.config.cjs", "--workers=1"];
224:      if (mode === "diagnostic") args.push("--max-failures=3");
225:      const execution = spawnSync("npx", args, {
226:        cwd: path.join(outputDir, "backend"),
227:        encoding: "utf8",
228:        timeout: remainingTimeout(180_000, deadlineAt),
229:        maxBuffer: 8 * 1024 * 1024,
230:        env: {
---src/runtime/runtimeReporter.ts
1:import { createHash } from "node:crypto";
2:import fs from "node:fs";
3:import path from "node:path";
4:
5:import type { AgentRuntime } from "arcbench-agent-runtime-js";
6:import type { NodeHandoff } from "../context/handoffStore.js";
7:import type { RequirementSet, WorkNode } from "../requirements/parser.js";
8:
9:function artifactId(prefix: string, nodeId: string, value: string, index: number): string {
10:  const digest = createHash("sha1").update(`${nodeId}\0${value}\0${index}`).digest("hex").slice(0, 10);
11:  return `${prefix}-${nodeId.replace(/[^A-Za-z0-9_-]/g, "-")}-${digest}`;
12:}
13:
14:function representedRequirementIds(node: WorkNode): string[] {
15:  return [...new Set(node.traceabilityIds?.length ? node.traceabilityIds : [node.id])];
16:}
17:
18:function scenarioSteps(description: string, acceptanceCriteria: string[]): Array<{ keyword: string; content: string }> {
19:  const steps: Array<{ keyword: string; content: string }> = [];
20:  if (description.trim()) steps.push({ keyword: "GIVEN", content: description.trim() });
21:  acceptanceCriteria.forEach((content) => steps.push({ keyword: "THEN", content }));
22:  return steps;
23:}
24:
25:function ensureAgentGitignore(projectDir: string): void {
26:  const filePath = path.join(projectDir, ".gitignore");
27:  const begin = "# BEGIN PI ARCBENCH AGENT";
28:  const end = "# END PI ARCBENCH AGENT";
29:  const block = [begin, "**/.arcbench-public/", "node_modules/", "dist/", "coverage/", end].join("\n");
30:  const current = fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8") : "";
31:  const withoutOldBlock = current.replace(new RegExp(`${begin}[\\s\\S]*?${end}\\n?`, "g"), "").trimEnd();
32:  fs.writeFileSync(filePath, `${withoutOldBlock}${withoutOldBlock ? "\n\n" : ""}${block}\n`, "utf8");
33:}
34:
35:export class RuntimeReporter {
36:  private readonly enabled: boolean;
37:  private readonly testIds = new Set<string>();
38:  private requirementIds: string[] = [];
39:
40:  constructor(private readonly runtime: AgentRuntime) {
41:    this.enabled = process.env.PI_ARCBENCH_RUNTIME !== "0";
42:  }
43:
44:  initialize(requirements: RequirementSet): void {
45:    if (!this.enabled) return;
46:    this.requirementIds = requirements.nodes.map((node) => node.id);
47:    const childrenByParent = new Map<string, string[]>();
48:    for (const node of requirements.nodes) {
49:      if (!node.parentId) continue;
50:      childrenByParent.set(node.parentId, [...(childrenByParent.get(node.parentId) || []), node.id]);
51:    }
52:    this.safe("initialize traceability", () => this.runtime.traceability.initDb());
53:    const requirementRows = requirements.nodes.map((node) => ({
54:        req_id: node.id,
55:        name: node.name,
56:        description: node.description,
57:        parent_id: node.parentId || null,
58:        children_ids: childrenByParent.get(node.id) || [],
59:        dependencies: node.dependencies,
60:        visual_reference: [],
61:        scenarios: node.scenarios.map((scenario) => ({
62:          id: scenario.id,
63:          name: scenario.name,
64:          steps: scenarioSteps(scenario.description, scenario.acceptanceCriteria),
65:        })),
66:    }));
67:    const scenarioRows = requirements.nodes.flatMap((node) => node.scenarios.map((scenario) => ({
68:          scenario_id: scenario.id,
69:          req_id: node.id,
70:          name: scenario.name,
71:          steps: scenarioSteps(scenario.description, scenario.acceptanceCriteria),
72:    })));
73:    const testRows = requirements.nodes.flatMap((node) => node.relatedTests.map((filePath, index) => {
74:        const testId = artifactId("TEST-SPEC", node.id, filePath, index);
75:        this.testIds.add(testId);
76:        return {
77:          test_id: testId,
78:          req_id: node.id,
79:          type: "DECLARED",
80:          file_path: filePath,
81:          first_line: "1",
82:          interface_ids: [],
83:          passed: null,
84:        };
85:    }));
86:    this.safe("register requirement set", () => this.runtime.traceability.registerRequirementSet({
87:      requirements: requirementRows,
88:      scenarios: scenarioRows,
89:      tests: testRows,
90:      node_states: requirements.nodes.map((node) => ({ req_id: node.id, state: "PENDING", phase: null })),
91:    }));
92:    this.safe("initialize git", () => {
93:      this.runtime.git.ensureRepo({ createInitialCommit: false });
94:      this.runtime.git.ensureArcGitignore();
95:      ensureAgentGitignore(this.runtime.paths.projectDir);
96:      this.runtime.git.configureIdentity();
97:      this.runtime.git.commit("ARC: initialize generated workspace");
98:    });
99:    this.safe("mark run started", () => this.runtime.events.markRunStarted("Requirement compilation started"));
100:  }
101:
102:  beginNode(node: WorkNode, attempt: number): string | null {
103:    if (!this.enabled) return null;
104:    const reqIds = representedRequirementIds(node);
105:    this.safe(`start ${node.id}`, () => this.runtime.events.markNodesStarted(reqIds, `Execution package ${node.id}, attempt ${attempt}`));
106:    return this.safeResult("capture checkpoint", () => this.runtime.git.currentHead(), null);
107:  }
108:
109:  completeNode(node: WorkNode, handoff: NodeHandoff): void {
110:    if (!this.enabled) return;
111:    const reqIds = representedRequirementIds(node);
112:    this.safe(`complete ${node.id}`, () => this.runtime.events.markNodesCompleted(reqIds, handoff.summary || `${node.id} implemented`));
113:
114:    const interfaceIds = handoff.interfaces_added.map((content, index) => {
115:      const interfaceId = artifactId("IF", node.id, content, index);
116:      this.safe(`register interface ${interfaceId}`, () => this.runtime.traceability.upsertInterface({
117:        interface_id: interfaceId,
118:        req_ids: reqIds,
119:        type: "GENERATED",
120:        content,
121:        file_path: handoff.files_created[index] || handoff.files_modified[index] || null,
122:        first_line: "1",
123:        implemented: true,
124:      }));
125:      this.safe(`complete interface ${interfaceId}`, () => this.runtime.traceability.setInterfaceImplemented(interfaceId, true, node.id));
126:      return interfaceId;
127:    });
128:
129:    handoff.tests_run.forEach((content, index) => {
130:      const testId = artifactId("TEST-RUN", node.id, content, index);
131:      this.testIds.add(testId);
132:      this.safe(`register executed test ${testId}`, () => this.runtime.traceability.upsertTest({
133:        test_id: testId,
134:        req_id: reqIds[0] || node.id,
135:        type: "AGENT_VALIDATION",
136:        file_path: null,
137:        first_line: null,
138:        interface_ids: interfaceIds,
139:        passed: null,
140:      }));
141:    });
142:
143:    this.safe(`checkpoint ${node.id}`, () => this.runtime.git.commit(`ARC ${node.id}: implementation checkpoint`));
144:  }
145:
146:  failNode(node: WorkNode, message: string): void {
147:    if (!this.enabled) return;
148:    this.safe(`fail ${node.id}`, () => this.runtime.events.markNodesFailed(representedRequirementIds(node), message));
149:  }
150:
151:  blockNode(node: WorkNode, _message: string): void {
152:    if (!this.enabled) return;
153:    this.safe(`block ${node.id}`, () => this.runtime.traceability.upsertNodeStates(
154:      representedRequirementIds(node).map((reqId) => ({ req_id: reqId, state: "BLOCKED", phase: "dependency" })),
155:    ));
156:  }
157:
158:  restoreCheckpoint(commitOid: string | null): void {
159:    if (!this.enabled || !commitOid || process.env.PI_ROLLBACK_FAILED_ATTEMPTS === "0") return;
160:    this.safe(`restore checkpoint ${commitOid}`, () => {
161:      this.runtime.git.resetToCommit(commitOid, { hard: true });
162:      this.runtime.git.cleanUntracked();
163:    });
164:  }
165:
166:  finalize(passed: boolean, message: string): void {
167:    if (!this.enabled) return;
168:    const primaryReqId = this.requirementIds[0] || "ARC-TASK";
169:    const finalTestId = "TEST-FINAL-VALIDATION";
170:    this.testIds.add(finalTestId);
171:    this.safe("register final validation", () => this.runtime.traceability.upsertTest({
172:      test_id: finalTestId,
173:      req_id: primaryReqId,
174:      type: "FINAL_VALIDATION",
175:      file_path: null,
176:      interface_ids: [],
177:      passed,
178:    }));
179:    this.safe("set final test statuses", () => this.runtime.traceability.setTestPassStatuses(
180:      passed
181:        ? Object.fromEntries([...this.testIds].map((testId) => [testId, true]))
182:        : { [finalTestId]: false },
183:    ));
184:    if (passed) {
185:      this.safe("pass requirements", () => this.runtime.events.markNodesTestPassed(this.requirementIds, message));
186:      this.safe("complete run", () => this.runtime.events.markRunCompleted(message));
187:      this.safe("final checkpoint", () => this.runtime.git.commit("ARC: validated final implementation"));
188:    } else {
189:      this.safe("fail final validation", () => this.runtime.events.markTestFailed(primaryReqId, message));
190:      this.safe("fail run", () => this.runtime.events.markRunFailed(message));
191:    }
192:  }
193:
194:  private safe(label: string, operation: () => unknown): void {
195:    try {
196:      operation();
197:    } catch (error) {
198:      console.warn(`[arcbench-runtime] ${label} failed without stopping generation: ${error instanceof Error ? error.message : String(error)}`);
199:    }
200:  }
201:
202:  private safeResult<T>(label: string, operation: () => T, fallback: T): T {
203:    try {
204:      return operation();
205:    } catch (error) {
206:      console.warn(`[arcbench-runtime] ${label} failed without stopping generation: ${error instanceof Error ? error.message : String(error)}`);
207:      return fallback;
208:    }
209:  }
210:}
